/* From Uiverse.io by Cksunandh  - Tags: form */
.__UIV_SCOPE__ .file-upload-container {
  width: 50%;
  max-width: 500px;
}

.__UIV_SCOPE__ .file-upload {
  position: relative;
  border: 2px dashed #b8bcbf;
  border-radius: 10px;
  padding: 40px;
  text-align: center;
  background-color: rgb(255, 255, 255);
  transition: background-color 0.3s ease-in-out;
}

.__UIV_SCOPE__ .file-upload:hover {
  background-color: #e2e6ea;
}

.__UIV_SCOPE__ .file-input {
  display: none;
}

.__UIV_SCOPE__ .file-label {
  display: flex;
  flex-direction: column;
  align-items: center;
  cursor: pointer;
}

.__UIV_SCOPE__ .upload-icon {
  font-size: 50px;
  color: #007bff;
  margin-bottom: 10px;
}

.__UIV_SCOPE__ .file-upload p {
  margin: 0;
  font-size: 16px;
  color: #6c757d;
}

.__UIV_SCOPE__ .file-upload.dragover {
  background-color: #007bff;
  color: white;
}
